INSERT INTO arcs (slug, title, description, start_episode, end_episode) VALUES
  ('conan-arc', 'Conan Arc', 'A shrunken detective builds a new life — and a secret mission.', 1, 128),
  ('sherry-arc', 'Sherry Arc', 'A defector from the Organization joins Conan''s side.', 129, 178),
  ('vermouth-arc', 'Vermouth Arc', 'A master of disguise who somehow knows Conan''s secret.', 179, 345),
  ('cell-phone-arc', 'Cell Phone Arc', 'Conan gets dangerously close to the boss himself.', 346, 424),
  ('kir-arc', 'Kir Arc', 'A three-way war between the FBI, the CIA, and the Organization.', 425, 508),
  ('bourbon-arc', 'Bourbon Arc', 'Who is Bourbon? Three newcomers, one hidden agent.', 509, 783),
  ('rum-arc', 'Rum Arc — Scarlet Series', 'The hunt for the No. 2 — and the boss is finally named.', 784, 1209)
INSERT INTO content_entries (slug, title, type, episode_number, movie_number, air_date, canon_order, synopsis, runtime_minutes, image_url) VALUES
  ('ep-001', 'Roller Coaster Murder Case', 'episode', 1, NULL, '1996-01-08', 1, 'High school detective Shinichi Kudo witnesses a murder on a roller coaster and is poisoned by the Black Organization, shrinking into a child.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
  ('ep-002', 'Company President''s Daughter Kidnapping Case', 'episode', 2, NULL, '1996-01-15', 2, 'Conan solves a kidnapping case involving a company president''s daughter, showcasing his deductive abilities in his new form.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
  ('ep-003', 'An Idol''s Locked Room Murder Case', 'episode', 3, NULL, '1996-01-22', 3, 'A famous idol is found murdered in a locked room. Conan must figure out how the killer escaped.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
  ('ep-004', 'Coded Map of the City Case', 'episode', 4, NULL, '1996-01-29', 4, 'The Detective Boys follow a coded map that leads them into danger across the city.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
  ('ep-005', 'The Shinkansen''s Big Mystery', 'episode', 5, NULL, '1996-02-05', 5, 'On a bullet train ride, Conan encounters a bombing threat and must find the bomb before time runs out.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
  ('ep-006', 'Valentine''s Murder Case', 'episode', 6, NULL, '1996-02-12', 6, 'A Valentine''s Day party turns deadly when one of the guests is found murdered.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
  ('ep-007', 'Once-A-Month Present Threat Case', 'episode', 7, NULL, '1996-02-19', 7, 'Ran receives threatening gifts every month from an anonymous sender. Conan investigates the stalker.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
  ('ep-008', 'Art Museum Owner Murder Case', 'episode', 8, NULL, '1996-02-26', 8, 'The owner of an art museum is murdered and a valuable painting is stolen.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
  ('ep-009', 'Tenkaichi Fire Festival Murder Case', 'episode', 9, NULL, '1996-03-04', 9, 'During a fire festival, a man is found dead. Conan suspects it was not an accident.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
  ('ep-010', 'Pro Soccer Player Threatening Case', 'episode', 10, NULL, '1996-03-11', 10, 'A professional soccer player is being threatened, and Conan must find the culprit before the big match.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
  ('ep-011', 'Moonlight Sonata Murder Case', 'episode', 11, NULL, '1996-03-18', 11, 'On a remote island, Conan investigates murders connected to Beethoven''s Moonlight Sonata. One of the most iconic early cases.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
  ('ep-012', 'Ayumi-chan Kidnapping Case', 'episode', 12, NULL, '1996-03-25', 12, 'Ayumi is kidnapped, and the Detective Boys must work with Conan to rescue her.', 25, 'https://cdn.myanimelist.net/images/anime/7/75199l.jpg'),
